#!/usr/bin/env python3
# Generate the Korean spoken-script document with SLIDE NUMBERS -> script_ko.docx
import os
from docx import Document
from docx.shared import Pt, Cm, RGBColor
from docx.oxml.ns import qn

HERE = os.path.dirname(os.path.abspath(__file__))
OUT = os.path.join(HERE, "..", "script_ko.docx")
TITLE = "Advancing Drug Discovery and Development through Clinical Pharmacological Approaches on Organs-on-Chips — presentation script (KBCS 2026, 49 slides, revised 2026-07)"
NAVY = RGBColor(0x16, 0x3A, 0x5F)

SLIDES = [
(1, "Title",
 "Good afternoon. I am Sungpil Han, of the Department of Pharmacology and the Department of Clinical Pharmacology at the Catholic University of Korea College of Medicine, Seoul St. Mary's Hospital, and the PIPET pharmacokinetics laboratory. Today's title is ‘Advancing organ-on-chip based drug development through a clinical pharmacology approach’. It is a great privilege to be presenting in the unmet clinical needs session of the Korean BioChip Society."),
(2, "Presentation overview",
 "Today I will first set out why preclinical systems keep failing to translate, and how the FDA is shifting the regulatory centre of gravity towards new approach methodologies, NAMs, and then explain how clinical pharmacology, in the form of QSP and PBPK, becomes the bridge. I will then introduce the autonomous LLM-based open QSP library we have built, currently 258 diseases, show a number of well-matched drug and disease cases including twelve case studies and six deep dives, then give a condensed account of the gut-liver-kidney chip and PBPK coupling study we carried out ourselves, and finally cover our plans for a web platform and the proposal we bring to this society."),
(3, "Unmet need: why preclinical systems fail to translate",
 "Getting a drug to approval usually takes 10 to 15 years and one to two point six trillion won, and about 90 percent of the candidates that enter clinical trials never reach a patient. Two-dimensional cell culture cannot reproduce tissue architecture or organ-level function, and animal models still carry cross-species pharmacokinetic differences. Phase 1 trials in healthy volunteers characterise exposure well, but the very patient groups where the uncertainty is greatest, such as inflammatory bowel disease, acute kidney injury, hepatic impairment, pregnant women, children and rare disease, are for the most part excluded."),
(4, "The regulatory shift: from mandated animal testing to NAMs",
 "Ever since the 1938 US Federal Food, Drug, and Cosmetic Act, the law has compelled a new drug to pass through animal testing before it is used in people. The 2022 FDA Modernization Act 2.0 changed the words ‘animal testing’ in the statute to ‘nonclinical testing’, explicitly permitting in vitro and in silico methods as well. The roadmap for reducing animal testing in preclinical safety studies published by the FDA in 2025 sets out a phased reduction of animal testing beginning with monoclonal antibodies, with the long-term goal that animal testing becomes the exception rather than the default. The repeatedly observed fact that a substantial proportion of the drugs which pass animal testing then fail in human trials is the core rationale for this policy shift."),
(5, "Why this matters for organ-on-chip",
 "The US FDA Modernization Act 2.0 has left the door open for NAMs, including MPS, to replace some animal testing. MIDD is already an established route on which regulators expect a quantitative package at the level of PBPK and QSP, and integrating MPS data into these workflows is a credible path to regulatory acceptance. Placing organ-on-chip inside the clinical pharmacology workflow redefines microphysiological system data as a translational bridge that reduces animal testing and brings candidate selection forward."),
(6, "The NAM translation loop — where clinical pharmacology sits",
 "I am showing you, unchanged, the figure from Cao's review published in Clinical Pharmacology & Therapeutics in 2025. It is a loop in which the signals generated by new approach methodologies, NAMs, such as organoids, organ-on-chip, two- and three-dimensional culture and in silico methods, pass through data science and AI/ML tools and connect into biological and clinical datasets. In this loop, the step that qualifies and translates a context of use into clinical meaning a regulator will accept is handled not by AI/ML pattern matching but by mechanistic models such as PBPK and QSP. Clinical pharmacology is not an ornament on this loop; it is its central axis."),
(7, "From a chip curve to a dose decision",
 "What a chip gives you is a concentration-time curve and single- or multi-organ readouts, mechanistically rich signals from human cells. But these are descriptive observations only, and a dose decision needs clearance, tissue distribution and target binding converted to the scale of the whole human body. Non-compartmental analysis, PBPK and QSP are precisely that bridge, and this is the theme of the whole of today's talk."),
(8, "What are QSP and PBPK",
 "PBPK and QSP are fields that combine systems biology with pharmacokinetics and pharmacodynamics, describing in mathematics the causal chain that runs from drug to target, pathway, disease and patient. PBPK answers where a drug goes in the whole human body and how much of it there is, and QSP answers the next question, namely what happens to the disease at that concentration. Put the two together and you can answer dose selection, drug-drug interactions, response in special populations, and even the IVIVE of chip data."),
(9, "Anatomy of a PBPK and a QSP model",
 "Mathematically this is a coupled nonlinear dynamical system, that is, an initial value problem. The state variables are drug concentrations, receptor occupancy, signalling molecules, cell populations, biomarkers and clinical endpoints; the parameters are rate constants, half-maximal effect concentrations, maximum effects, clearances and binding affinities; and the input is the dosing regimen, the only handle we can turn. The models in our library usually consist of 15 to 35 or more differential equations and seventy to over a hundred parameters."),
(10, "Recurring nonlinear structures",
 "Even when the disease changes, the mathematical structure recurs. The Hill and Emax pharmacodynamic expressions, the indirect response model as a balance of synthesis and degradation, target-mediated drug disposition, logistic growth as seen in tumours and in vascular remodelling, and power-law feedback such as that of erythropoietin: the five motifs you see in this table are a common grammar that appears identically in the 258 QSP models and on both sides of the chip-to-PBPK bridge I will show later today."),
(11, "Why this matters — model-informed drug development",
 "PBPK and QSP are core tools of model-informed drug development, MIDD, which the regulators themselves recommend. They weed out hopeless targets early at the target validation stage, set the first-in-human dose on mechanistic grounds, design trials with virtual patients, support extrapolation from chip to animal to human, and explore the synergy of combinations in advance. Regulators are already actively behind this."),
(12, "The bottleneck: what one QSP model traditionally costs",
 "From synthesising a vast literature, through setting up and parameterising the differential equations, to software implementation and calibration, one QSP model traditionally takes an expert months to years. As a result only a handful of diseases get a model, the models are closed and hard to reproduce, and most of the diseases in the long tail, which is to say most of the diseases that chip programmes address, never obtain a model at all."),
(13, "The core proposal: LLM-based model generation",
 "Our proposal is to use an autonomous large language model coding agent to build complete, quality-controlled, literature-anchored QSP models at a rate of one disease per day. Each model consists of four artefacts, a Graphviz mechanistic map, an mrgsolve differential equation model, a Shiny dashboard and an organised reference list, and follows built-in principles of quality gates, literature anchoring, a standardised schema and reproducible code."),
(14, "Claude Code Routine — the autonomous daily loop",
 "This engine is a schedule-based coding agent that runs roughly once a day, and each time it runs it completes one disease from beginning to end and pushes it. It picks an uncovered disease, synthesises about 50 papers, draws a map with more than a hundred nodes, writes 15 or more differential equations, builds a dashboard with 6 or more tabs, organises the references, and then commits and pushes automatically under the compulsion of a Git stop hook that makes it impossible to end a session half finished."),
(15, "Safeguards — how do you trust code an LLM wrote",
 "Quality gates are enforced: at least a hundred nodes and 8 clusters for the map, at least 15 compartments and 5 scenarios for the model, at least 6 tabs for the dashboard, and at least 30 papers for the references. Reusable structural templates such as Hill, turnover and TMDD reduce the room to go wrong, every parameter carries a calibration note citing a clinical trial which guards against hallucination, everything is code inside Git so it can be diffed and audited, and a human reviews it before use."),
(16, "Why an LLM/AI is the right engine",
 "Completing a multi-artefact disease model almost every day, working continuously without tiring, is a pace no human team can sustain. Across the whole library it integrates about twelve thousand eight hundred papers, handles 258 diseases and hundreds of drugs and targets within one consistent framework, is standardised and therefore comparable, and turns an expert's months into hours."),
(17, "What is in each model",
 "Every model consistently provides four things: a mechanistic map running from pathway to target to disease; an mrgsolve differential equation model combining drug pharmacokinetics with disease pharmacodynamics, carrying 15 to 35 or more state variables; an interactive Shiny dashboard showing patient profile, PK and endpoints; and about 50 references per model. This is exactly the structure your chip data should be connecting to."),
(18, "Scale: an open QSP library of 258 models",
 "There are currently 258 disease models, about 18 therapeutic areas, 259 differential equation systems, about three thousand one hundred pathway clusters and about twelve thousand eight hundred references, and it still grows by roughly one a day. Where traditional QSP spent an expert's months on each of a handful of diseases, this library spends a few hours on each of 258 diseases: not an incremental improvement but a step change."),
(19, "Breadth of coverage",
 "From oncology, autoimmunity, vasculitis, cardiovascular, respiratory, renal, gastrointestinal, endocrine, neurological, psychiatric, dermatological, infectious and ophthalmic disease through to rare genetic disease, one consistent framework runs across the spectrum of human disease. It contains hundreds of drugs and targets, from cancers such as breast and lung cancer, through rare diseases such as Fabry disease, chronic diseases such as diabetes and heart failure, to immune and haematological diseases such as lupus and sickle cell disease, so there is a very good chance that something relevant to your chip is already in there."),
(20, "Case studies: drug, target, endpoint",
 "This table is a part of the drug-target-endpoint relationships the library already covers. Tocilizumab in rheumatoid arthritis, secukinumab in psoriasis, semaglutide in type 2 diabetes, sacubitril-valsartan in heart failure, triple therapy in chronic obstructive pulmonary disease, osimertinib in non-small cell lung cancer, imatinib in chronic myeloid leukaemia, macitentan in pulmonary arterial hypertension, sparsentan in IgA nephropathy, voxelotor in sickle cell disease, daratumumab in multiple myeloma, and merigolix in endometriosis: every drug-target-endpoint relationship is grounded in the clinical literature."),
(21, "Case studies — one insight each (1/4)",
 "In non-small cell lung cancer the model predicts when resistant clones will emerge against osimertinib, giving a rationale for combination or sequential therapy. In heart failure with reduced ejection fraction it explores the dosing order and up-titration rate of four agents against reverse remodelling. In transthyretin amyloidosis it follows the tetramer-monomer kinetics of gene silencing therapy and the organ burden over several years."),
(22, "Case studies — one insight each (2/4)",
 "In systemic lupus erythematosus it links the chain by which an anti-interferon antibody suppresses interferon signalling. In type 2 diabetes it looks at the glucose-insulin-weight feedback of incretin drugs. In immune thrombocytopenia it looks at the effect of a thrombopoietin receptor agonist through the balance of platelet production and destruction."),
(23, "Case studies — one insight each (3/4)",
 "Romosozumab is an anti-sclerostin antibody that creates a transient uncoupling window during the first twelve months in which bone formation runs ahead of resorption, and the model shows that the timing of the switch to an antiresorptive before that window closes matters. Erenumab is an anti-CGRP-receptor antibody whose slow clearance maintains receptor occupancy even on once-monthly dosing, and receptor occupancy matches the reduction in monthly migraine days better than the plasma concentration does. Dupilumab blocks IL-4 and IL-13 signalling simultaneously, and biomarkers such as IgE and TARC move early while the clinical response measured by EASI appears later than that."),
(24, "Case studies — one insight each (4/4)",
 "Emicizumab is a bispecific antibody that mimics factor VIII, but the aPTT shortens far more than the actual haemostatic effect, so modelling has to reconnect thrombin generation with the real reduction in bleeding rate. Efgartigimod is an FcRn antagonist that lowers total IgG by about 60 percent within days, but the MG-ADL symptom improvement appears later than that, which supports a cyclic rather than a continuous dosing strategy. Pegloticase degrades urate effectively at first, but makes it possible to predict the loss of response as anti-drug antibodies against PEG-uricase accumulate."),
(25, "Deep dive — IgA nephropathy",
 "We modelled the four-hit hypothesis that starts from galactose-deficient IgA1 and runs through autoantibody, immune complex, and mesangial deposition with complement activation. It contains five drugs, RAAS blockade, budesonide, sparsentan, iptacopan and sibeprenlimab, and proteinuria and the eGFR slope were calibrated against the major clinical trials. Twenty differential equations, seven scenarios."),
(26, "Deep dive — sickle cell disease",
 "We modelled the chain that starts from the polymerisation of deoxygenated HbS and runs through haemolysis, nitric oxide consumption, endothelial activation and vaso-occlusive crisis. It contains hydroxyurea, voxelotor, crizanlizumab and L-glutamine, and haemoglobin, the fetal haemoglobin fraction and vaso-occlusion frequency were calibrated against the major clinical trials. It includes twenty-four differential equations and power-law haematopoietic feedback."),
(27, "Deep dive — multiple myeloma",
 "We modelled monoclonal protein secretion by a bone marrow plasma cell clone, autocrine interleukin-6 growth, and bone disease driven by the RANKL-OPG imbalance. It contains a proteasome inhibitor, lenalidomide, daratumumab, venetoclax and zoledronic acid, and tracks M protein and free light chains under several standard combination regimens. It is the representative oncology case, combining logistic growth with a resistant clone and target-mediated disposition."),
(28, "Deep dive — rheumatoid arthritis",
 "In the synovium, IL-6, TNF and JAK signalling lead on to pannus formation and cartilage and bone erosion, and CRP is the acute-phase marker reflecting IL-6 trans-signalling. It contains methotrexate, tocilizumab, adalimumab and baricitinib, and tracks DAS28, CRP and bone erosion under monotherapy and combination therapy. Nineteen differential equations, seven scenarios."),
(29, "Deep dive — Duchenne muscular dystrophy",
 "When a mutation in the dystrophin gene causes loss of the protein, the muscle cell membrane weakens, chronic necrosis and regeneration repeat, and the muscle is eventually replaced by fibrofatty tissue with a progressive decline in strength. It contains deflazacort, prednisone, the exon 51 skipping antisense oligonucleotide eteplirsen, and the HDAC inhibitor givinostat, and tracks the dystrophin restoration fraction and the functional decline trajectory. Twenty-two differential equations, six scenarios."),
(30, "Deep dive — Alzheimer's disease",
 "An imbalance between the production and the clearance of amyloid beta leads to plaque accumulation, the loss of synapses and cholinergic neurons causes progressive cognitive decline, and the APOE4 genotype accelerates this course. It contains donepezil, memantine and the anti-amyloid antibody lecanemab, and tracks plaque burden and an MMSE surrogate cognitive score under genotype- and mutation-specific scenarios. Twenty differential equations, seven scenarios."),
(31, "Flagship case — merigolix, a genuinely live drug-disease model",
 "Merigolix is an oral gonadotropin-releasing hormone antagonist for endometriosis which lowers luteinising hormone and follicle-stimulating hormone to suppress oestradiol and reduce lesions and pain. It combines two-compartment pharmacokinetics with hypothalamic-pituitary-gonadal axis pharmacodynamics, and ties pain, lesion size, hot flushes, bone mineral density and endometrial thickness together into one system of differential equations. You can reach the actually deployed dashboard right now at the address at the bottom of the screen."),
(32, "Merigolix — the oestrogen threshold trade-off",
 "If oestradiol is suppressed too little there is no symptom relief, and if it is suppressed too much hot flushes and bone loss follow. In this simulation pain fell from three point one to one point one and the lesion from eighteen point five to five point three millimetres, but bone mineral density fell by one point two two percent and hot flushes increased. QSP turns this kind of clinical trade-off into a tractable optimisation problem."),
(33, "Gallery — part of the library",
 "These are some of the mechanistic maps, spanning oncology, autoimmunity, cardiovascular, renal, metabolic, neurological and rare disease. Each one is the product of a single autonomous build."),
(34, "How this directly helps your chip programme",
 "If you are building a chip for a cytokine, a transporter, a receptor or a disease, there is a good chance a relevant QSP model already exists. You can use it to obtain a research hypothesis before designing the chip experiment, or use it as the disease layer to place on top of your own chip-to-PBPK bridge, as in the case study I will show later today. The point is not that you should take on all 258 models, but that this becomes a platform which accelerates the translation of the molecules, drugs and diseases you already work on."),
(35, "Completely open",
 "At github.com/pipetcpt/qsp we publish every mechanistic map, differential equation model, Shiny dashboard and reference list, commit by commit. The QR code at the top right of every slide links straight to this repository."),
(36, "Future direction: a browser-based PBPK/QSP platform",
 "A complex differential equation system is a real barrier to entry. We want to build a web platform on which, with nothing installed and only a browser, you can search by disease, target or drug, look through the map and the differential equation structure, run a simple simulation in which you change the dose and see the graph immediately, and export those parameters into your own workflow."),
(37, "Preconditions for trusting the numbers that come out of a chip",
 "For chip numbers to be trusted inside a PBPK or QSP model, four things have to be checked: chip-specific behaviour such as adsorption to plastic; cell number scaling; validation against held-out clinical data; and explicit, falsifiable correction rules rather than arbitrary fitting to make the numbers agree. The case study I am about to show was designed precisely to test whether this principle is actually achievable."),
(38, "Our case study: gut-liver-kidney MPS + PBPK",
 "We connected a modular gut-liver-kidney MPS with a shared medium circulation and propagated the parameters fitted on the chip into a whole-body PBPK model. No human pharmacokinetic data entered the prediction process at all; all twenty-four clinical observations across six drugs were used for post hoc validation only. The overall AUC GMFE was 1.85-fold, and all twenty-four were within 4-fold."),
(39, "The model predicts human pharmacokinetics well",
 "This graph is the only original figure used in today's talk. On the left is predicted versus observed AUC, with a GMFE of 1.85-fold, fifteen within 2-fold and all twenty-four within 4-fold. On the right is Cmax, with a GMFE of 2.55-fold. We obtained agreement of this order for all six drugs, which act by six different mechanisms."),
(40, "How it works — from chip kinetics to whole-body PBPK",
 "A thirty-three-state system of differential equations closes the recirculation loop of the chip to fit the kinetics of drug and metabolite, and reflects OATP-like hepatic uptake through a Kpuu,hep term. The parameters obtained this way are passed into a ten-compartment perfusion-limited whole-body PBPK model, which represents the human body using Rodgers-Rowland tissue partitioning, the Varma extended clearance approach and an ACAT oral absorption model. The inputs are only physicochemical properties such as logP, pKa, plasma unbound fraction, plasma-to-blood ratio, molecular weight and dose; no human clinical pharmacokinetic data is used in the fitting at all."),
(41, "How it works — a falsifiable correction rule",
 "The key is a falsifiable correction rule. The in vitro-to-in vivo relative activity factor, RAF, is applied only when the CYP3A4 contribution is 90 percent or more, biliary clearance is under 50 percent, and hepatic uptake is not yet accounted for. This is not curve fitting but a mechanistically grounded test. Under blanket correction the GMFE was 9.7-fold, but applying this selective rule improved it to 1.85-fold. In the disease-state extension the same pipeline is applied unchanged, without re-parameterisation, holding the parameters of the unaffected organs fixed."),
(42, "Validation results — 24 observations, 6 drugs",
 "Performance was consistent across all six drugs of differing mechanism, antipyrine, benzylpenicillin, testosterone, crizotinib, gefitinib and simvastatin, with an overall GMFE of 1.85-fold and all twenty-four within 4-fold. This falls within the 2- to 5-fold benchmark range of industry-standard PBPK platforms."),
(43, "Disease-state extension: gut-local versus liver-local",
 "In the DSS colitis chip the AUC of gefitinib fell to 0.49-fold, and this was a gut-local phenomenon in which Fg changed while Fa and Fh stayed the same. In the cisplatin-injury chip the AUC of simvastatin rose to 2.19-fold, and this was a liver-local phenomenon in which the halving of Kpuu,liver was consistent with OATP1B1 inhibition. The same PBPK pipeline distinguishes gut-local from liver-local change, and generates hypotheses about those patient groups with inflammatory bowel disease or acute kidney injury who are normally excluded from phase 1 trials."),
(44, "The limitations, and what they mean",
 "The limitations are that the chip has no mucus layer and no peristalsis, which affects permeability; that the CYP3A4 activity of two-dimensional HepaRG culture is about 10 percent of that of the real liver (corrected with the RAF); that OAT1/3 activity in RPTEC is about 1 percent; and that clinical pharmacokinetic data in disease-state patients is scarce. It is implemented in open-source Python, and the entire run of six drugs and twenty-four observations reproduces on a laptop in under five minutes. This work does not replace animal and clinical pharmacokinetic data; it complements it."),
(45, "The unmet need in clinical pharmacology",
 "Before I conclude I would like to speak about the unmet need within clinical pharmacology itself. There is an absolute shortage of clinical pharmacologists trained in PBPK and QSP who can actually interpret NAM signals. Nor is there yet any standardised workflow for applying in practice the four principles of NAM validation the FDA requires, namely context of use, biological plausibility, technical characterisation and fitness for purpose. Cases in which chip and organoid data have been validated side by side with human clinical data are still rare, so the very grounds for saying that this model is correct are lacking. In the end the bottleneck is not the technology but the people to do the translating, and that is also part of why I am standing in front of you today."),
(46, "A proposal to the members of KBCS",
 "Now I would like to put a concrete proposal to you. From the chip design stage onwards, please also consider the quantitative outputs that can feed into PBPK and QSP, that is, values such as clearance, permeability and the absorbed fraction. I propose collaborative research that cross-validates your chip data against held-out clinical data; that was the core methodology of today's talk. Please try out the model corresponding to your chip and your disease from the 258-model QSP library I introduced today, and if it does not fit, tell us. That is what makes the next model better. We are waiting for collaboration at github.com/pipetcpt/qsp and by email."),
(47, "Conclusion and an open invitation",
 "Organ-on-chip does generate genuinely human-relevant biology, but for that to become evidence usable in decision-making it needs clinical pharmacology. Our gut-liver-kidney case shows that this is possible even without clinical pharmacokinetic data, and the 258-model QSP library exists so that this community can adopt these principles now rather than having to build them again from scratch. This project is completely open, and we would like to work together."),
(48, "Key references",
 "Cao's 2025 review on the role of the clinical pharmacologist, which runs through the whole of today's talk, the FDA's animal testing reduction roadmap and Modernization Act 2.0, and Van Norman's paper on the limitations of animal testing, together with DiMasi, Landis and Kola on the economics of drug development, Huh and colleagues' 2010 Science organ-on-chip paper, the reviews by Bhatia and Ingber, the Rodgers-Rowland tissue partitioning methodology and the Varma clearance methodology, are the methodological basis of today's talk."),
(49, "Contact",
 "I am Sungpil Han, associate professor at the Catholic University of Korea College of Medicine. I am in the Department of Pharmacology and the Department of Clinical Pharmacology, jointly with Seoul St. Mary's Hospital and the PIPET pharmacokinetics laboratory. My email is shan at catholic.ac.kr, and the QR code takes you straight to the open-source QSP library. Thank you for your attention. Questions and collaboration are both welcome."),
]

def set_ko(run):
    run.font.name = "Malgun Gothic"
    run.element.rPr.rFonts.set(qn("w:eastAsia"), "Malgun Gothic")

doc = Document()
st = doc.styles["Normal"]; st.font.name = "Malgun Gothic"; st.font.size = Pt(11)
st.element.rPr.rFonts.set(qn("w:eastAsia"), "Malgun Gothic")
for s in doc.sections:
    s.top_margin = s.bottom_margin = Cm(2.2); s.left_margin = s.right_margin = Cm(2.5)

p = doc.add_paragraph(); r = p.add_run(TITLE); r.bold = True; r.font.size = Pt(13); set_ko(r)
doc.add_paragraph("")
for n, title, text in SLIDES:
    hp = doc.add_paragraph(); hp.paragraph_format.space_before = Pt(8); hp.paragraph_format.space_after = Pt(3)
    hr = hp.add_run(f"[Slide {n}] {title}"); hr.bold = True; hr.font.size = Pt(11.5); hr.font.color.rgb = NAVY; set_ko(hr)
    for chunk in text.split("\n\n"):
        bp = doc.add_paragraph(chunk); bp.paragraph_format.line_spacing = 1.5; bp.paragraph_format.space_after = Pt(8)
        for rr in bp.runs: set_ko(rr)
doc.save(OUT)
print("saved", OUT, "slides:", len(SLIDES))
